import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Kernel definition (C++ source for the kernel only)
mul_kernel_cpp = """
__global__ void mul_kernel(const float* a, const uint8_t* m, float* out, int total) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total) {
        out[idx] = a[idx] * (m[idx] ? 1.0f : 0.0f);
    }
}
"""

# Wrapper function for element-wise multiplication by mask.
mul_cuda_source = """
torch::Tensor elementwise_mul_cuda(torch::Tensor x, torch::Tensor mask) {
    auto size = x.numel();
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    mul_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), (uint8_t*)mask.to_tensor().data_ptr(), out.data_ptr<float>(), size);

    return out;
}
"""

# Load the inline function.
mul_custom = load_inline(
    name="elementwise_mul",
    cpp_sources=mul_kernel_cpp,
    cuda_sources=mul_cuda_source,
    functions=["elementwise_mul_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.dim = 1
        self.elementwise_mul = mul_custom

    def forward(self, x, mask):
        prod = self.elementwise_mul(x, mask)
        return torch.cumsum(prod, dim=self.dim)
